"""Verify the real handler's output lifetime without a model or CUDA device."""
import ast
import contextlib
import importlib.util
from pathlib import Path
import sys
import types
import weakref


def test_raw_model_outputs_die_before_device_lease_is_returned(monkeypatch, tmp_path):
    root = Path(__file__).resolve().parents[1]
    path = root / "astrolabe/evaluators/wrappers/esmfold_daemon.py"
    tree = ast.parse(path.read_text())
    handle = next(node for node in ast.walk(tree)
                  if isinstance(node, ast.FunctionDef) and node.name == "handle")
    references, observed = {}, {}

    class Tensor:
        def __init__(self, device="device"):
            self.device = device
        def detach(self):
            return self
        def cpu(self):
            return Tensor("cpu")

    torch = types.SimpleNamespace(Tensor=Tensor, no_grad=contextlib.nullcontext)
    monkeypatch.setitem(sys.modules, "torch", torch)
    spec = importlib.util.spec_from_file_location(
        "lease_lifetime_lifecycle", root / "astrolabe/evaluators/lifecycle.py")
    lifecycle = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(lifecycle)

    class Model:
        def infer(self, sequences):
            result = {key: Tensor() for key in (
                "chain_index", "plddt", "mean_plddt", "ptm",
                "predicted_aligned_error", "unselected_scratch")}
            references.update({key: weakref.ref(value) for key, value in result.items()})
            return result
        def output_to_pdb(self, output):
            return ["PDB text"]

    @contextlib.contextmanager
    def operation(*args, **kwargs):
        yield types.SimpleNamespace(update_lifecycle=lambda **fields: None)
        observed["live_at_release"] = sum(ref() is not None for ref in references.values())

    def dump_tree(path, result):
        observed["live_at_encode"] = sum(ref() is not None for ref in references.values())
        observed["cpu_devices"] = [value.device for value in result["output"].values()]
        assert result["pdbs"] == ["PDB text"] and result["rng"] is None

    namespace = dict(
        request_directory=Path, load_tree=lambda _: {"sequences": ["AAA"], "rng": None},
        contextlib=contextlib, sys=sys, torch=torch, operation=operation, actual={},
        spec={"device": {"name": "cpu"}}, restore=lambda *args: None, model=Model(),
        cpu_tree=lifecycle.cpu_tree, capture=lambda _: None, lifecycle=lambda: {},
        dump_tree=dump_tree)
    exec(compile(ast.Module(body=[handle], type_ignores=[]), str(path), "exec"), namespace)
    namespace["handle"]({"request_dir": str(tmp_path)})
    assert observed == {"live_at_release": 0, "live_at_encode": 0, "cpu_devices": ["cpu"] * 5}

